def kepler_E(M, e):
    E = M + e*np.sin(M)
    for _ in range(60):
        dE = (E - e*np.sin(E) - M)/(1 - e*np.cos(E))
        E -= dE
        if np.max(np.abs(dE)) < 1e-13:
            break
    return E

def kepler_pos(t, a, e, inc, Om, om, M0, n):
    M = np.mod(M0 + n*t, 2*np.pi)
    E = kepler_E(M, e)
    x = a*(np.cos(E) - e); y = a*np.sqrt(1 - e*e)*np.sin(E)
    cO, sO = np.cos(Om), np.sin(Om); ci, si = np.cos(inc), np.sin(inc); co, so = np.cos(om), np.sin(om)
    X = (cO*co - sO*so*ci)*x + (-cO*so - sO*co*ci)*y
    Y = (sO*co + cO*so*ci)*x + (-sO*so + cO*co*ci)*y
    Z = (so*si)*x + (co*si)*y
    return np.stack([X, Y, Z], axis=-1)

def earth(t):
    return kepler_pos(t, 1.0, EE, INCE, OMEE, OMEGAE, M0E, NE)

def harm_eval(t, freqs, c):
    z = np.zeros(len(t), complex)
    for k, w in enumerate(freqs):
        z += c[2*k]*np.exp(1j*w*t) + c[2*k+1]*np.exp(-1j*w*t)
    return z

def unit_to_lonlat(u):
    return np.arctan2(u[:, 1], u[:, 0]) % (2*np.pi), np.arcsin(np.clip(u[:, 2], -1, 1))

def lonlat_to_unit(lon, lat):
    return np.stack([np.cos(lat)*np.cos(lon), np.cos(lat)*np.sin(lon), np.sin(lat)], axis=-1)

def body_direction(t, body):
    if body == 'S':
        rE = earth(t)
        return -rE/np.linalg.norm(rE, axis=1)[:, None]
    if body == 'M':
        p = kepler_pos(t, 1.0, *MOON)
        return p/np.linalg.norm(p, axis=1)[:, None]
    rp = kepler_pos(t, *ELEM[body]) - earth(t)
    return rp/np.linalg.norm(rp, axis=1)[:, None]

def predict_body(t, body):
    u = body_direction(t, body)
    if body in ('M', 'P3'):
        freqs, c = (M_FREQS, M_C) if body == 'M' else (P3_FREQS, P3_C)
        lon, lat = unit_to_lonlat(u)
        z = harm_eval(t, freqs, c)          # (dlon*cos(lat)) + i*dlat, radians
        lon = lon + z.real/np.cos(lat)
        lat = lat + z.imag
        return lon, lat
    return unit_to_lonlat(u)

def main():
    rows = list(csv.DictReader(open(HERE/'predictions.csv')))
    days = np.array([float(r['day']) for r in rows])
    bodies = [r['body'] for r in rows]
    lon_out = np.full(len(rows), np.nan); lat_out = np.full(len(rows), np.nan)
    for body in ['S', 'P1', 'P2', 'P3', 'P4', 'P5', 'M']:
        idx = np.array([i for i, b in enumerate(bodies) if b == body], dtype=int)
        lon, lat = predict_body(days[idx], body)
        lon_out[idx] = np.degrees(lon); lat_out[idx] = np.degrees(lat)
    with open(HERE/'predictions.csv', 'w', newline='') as f:
        w = csv.writer(f)
        w.writerow(['day', 'body', 'lon', 'lat'])
        for i, r in enumerate(rows):
            w.writerow([r['day'], r['body'], '%.5f' % lon_out[i], '%.5f' % lat_out[i]])
    print('wrote', len(rows), 'rows to', HERE/'predictions.csv')

if __name__ == '__main__':
    main()
